/**
 * Built-in collection view keys that should never be treated as custom views.
 */
const builtInViewKeys = ['edit', 'list']

export const getCustomCollectionViewByRoute = ({
  adminRoute,
  baseRoute,
  currentRoute: currentRouteWithAdmin,
  views,
}: {
  adminRoute: string
  baseRoute: string
  currentRoute: string
  views: SanitizedCollectionConfig['admin']['components']['views'] | undefined
}): {
  view: {
    payloadComponent?: PayloadComponent<AdminViewServerProps>
  }
  viewKey: null | string
} => {
  if (!views || typeof views !== 'object') {
    return {
      view: {},
      viewKey: null,
    }
  }

  const currentRoute =
    adminRoute === '/' ? currentRouteWithAdmin : currentRouteWithAdmin.replace(adminRoute, '')

  for (const [viewKey, view] of Object.entries(views)) {
    if (builtInViewKeys.includes(viewKey)) {
      continue
    }

    if (!view || typeof view.path !== 'string' || !view.Component) {
      continue
